export const BODY: string = "\n<p>DPI اور PPI تصویر سازی میں سب سے زیادہ الجھایا گیا جوڑا ہیں۔ لوگ انہیں ایک دوسرے کی جگہ استعمال کرتے ہیں، ٹول انہیں غیر مستقل لیبل کرتے ہیں، اور نتیجہ غلط مشوروں کی گڑبڑ ہوتا ہے۔</p>\n<p>الجھن کی حقیقی قیمت ہوتی ہے۔ ڈیزائنر ویب تصاویر پر 300 DPI سیٹ کرتے ہیں جنہیں اس کی ضرورت نہیں، اور پرنٹ خریدار 72 DPI فائلیں قبول کرتے ہیں جو کبھی اچھی پرنٹ نہیں ہوں گی۔</p>\n<p>یہ مضمون دونوں اصطلاحوں کو صاف الگ کرتا ہے، بتاتا ہے کہ ہر ایک کہاں اہمیت رکھتی ہے، اور کسی بھی صورتحال میں یہ فیصلہ کرنے کا آسان اصول دیتا ہے کہ کس نمبر کی پرواہ کریں۔</p>\n<h2 id=\"dpi-defined\">DPI کی تعریف: سیاہی کے نقطے</h2>\n<p>DPI کا مطلب dots per inch ہے، اور یہ پرنٹرز سے تعلق رکھتا ہے۔ یہ سیاہی کے چھوٹے نقطے گنتا ہے جو پرنٹر ایک انچ کاغذ میں رکھتا ہے، اور یہ طے کرتا ہے کہ پرنٹ کتنا باریک ہو گا۔</p>\n<p>300 DPI والا پرنٹر فی انچ 300 سیاہی نقطے رکھ سکتا ہے۔ 600 DPI والا پرنٹر دوگنا رکھ سکتا ہے، اسی لیے فائن آرٹ پرنٹ زیادہ قدر استعمال کرتے ہیں۔</p>\n<p>تصویر فائلوں میں DPI میٹا ڈیٹا ٹیگ ہوتا ہے جو سافٹ ویئر کو مطلوبہ پرنٹ کثافت بتاتا ہے۔ یہ پکسل نہیں بدلتا؛ یہ پرنٹر کو بتاتا ہے کہ انہیں کاغذ پر کیسے فاصلے سے رکھیں۔</p>\n<p>جب کوئی پلیٹفارم 300 DPI مانگے تو یہ اسی ٹیگ کو مانگ رہا ہوتا ہے۔ یہ چاہتا ہے کہ فائل اعلان کرے کہ اس کے پکسل فی انچ 300 کی کثافت سے رکھے جانے کے لیے ہیں۔</p>\n<h2 id=\"ppi-defined\">PPI کی تعریف: اسکرین پر پکسل</h2>\n<p>PPI کا مطلب pixels per inch ہے، اور یہ اسکرینوں سے تعلق رکھتا ہے۔ یہ گنتا ہے کہ ڈسپلے اپنی سطح کے ایک انچ میں کتنے جسمانی پکسل پیک کرتا ہے۔</p>\n<p>400 PPI اسکرین والا فون ہر انچ میں 400 پکسل نچوڑتا ہے، اسی لیے متن چھوٹے سائز پر بھی تیز لگتا ہے۔ 96 PPI والا پرانا مانیٹر وہی متن نرم دکھاتا ہے۔</p>\n<p>PPI ڈسپلے ہارڈ ویئر کی خاصیت ہے، تصویر فائل کی نہیں۔ آپ فائل ایڈٹ کر کے اسکرین PPI نہیں بدل سکتے، جیسے آپ فائل ایڈٹ کر کے مانیٹر سائز نہیں بدل سکتے۔</p>\n<p>کچھ تصویر ایڈیٹر PPI کو اسی میٹا ڈیٹا ٹیگ کا لیبل استعمال کرتے ہیں جسے دوسرے DPI کہتے ہیں۔ یہ اوورلیپ ہی بنیادی وجہ ہے کہ دونوں اصطلاحیں مل جاتی ہیں۔</p>\n<h2 id=\"why-they-get-confused\">DPI اور PPI کیوں الجھ جاتے ہیں</h2>\n<p>الجھن کی تین وجوہات ہیں۔ پہلی، اصطلاحیں ایک جیسی لگتی ہیں اور دونوں میں انچ شامل ہیں۔ دوسری، کچھ سافٹ ویئر انہیں اسی فائل ٹیگ کے مترادف استعمال کرتا ہے۔ تیسری، دو صنعتیں ایک نمبر کو مختلف نام دیتی ہیں۔</p>\n<p>Photoshop، مثال کے طور پر، فائل ریزولوشن فیلڈ کو PPI لیبل کرتا ہے، جبکہ پرنٹ شاپ اسی نمبر کو DPI کہتی ہے۔ فائل میں ایک نمبر ہوتا ہے، اور دو صنعتیں اسے دو نام دیتی ہیں۔</p>\n<p>عملی حل یہ پوچھنا ہے کہ نمبر کیا کنٹرول کرتا ہے۔ اگر یہ کاغذ پر سیاہی کنٹرول کرے تو DPI سوچیں۔ اگر یہ اسکرین پر پکسل کنٹرول کرے تو PPI سوچیں۔ سیاق بتاتا ہے کہ کون سا ہے۔</p>\n<p>خود فائل ٹیگ کے لیے فرق بمشکل اہمیت رکھتا ہے۔ چاہے فیلڈ کو DPI کہا جائے یا PPI، اس میں وہی قدر ہوتی ہے، اور امیج DPI چینجر اسے درست لکھتا ہے۔</p>\n<h2 id=\"print-what-matters\">پرنٹ: DPI ہی اہمیت رکھتا ہے</h2>\n<p>پرنٹ میں DPI تیزی کے بارے میں سب کچھ طے کرتا ہے۔ 300 DPI پر پرنٹ شدہ 3000 پکسل تصویر 10 انچ گھیرتی ہے، جبکہ 150 DPI پر وہی پکسل 20 انچ گھیرتے ہیں اور نرمی سے۔</p>\n<p>پرنٹ معیار ہاتھ میں رکھی ہر چیز کے لیے 300 DPI ہے: کتابیں، بروشر، رسائل، اور پیکجنگ۔ اس کثافت پر آنکھ انفرادی نقطے نہیں دیکھ سکتی۔</p>\n<p>بڑے پرنٹ اصول کو نرم کرتے ہیں۔ دو میٹر دور سے دیکھا گیا پوسٹر 150 DPI پر ٹھیک لگتا ہے، اور سڑک سے دیکھا گیا بل بورڈ 50 DPI یا اس سے نیچے جا سکتا ہے بغیر نقصان کے۔</p>\n<p>کسی بھی پرنٹ کام سے پہلے پکسل کو DPI سے تقسیم کر کے جسمانی سائز حاصل کریں۔ اگر نتیجہ آپ کی ضرورت سے چھوٹا ہو تو زیادہ پکسل لیں یا چھوٹا پرنٹ قبول کریں۔</p>\n<h2 id=\"web-what-matters\">ویب: پکسل اہمیت رکھتے ہیں، DPI نہیں</h2>\n<p>ویب پر براؤزر DPI ٹیگ کو مکمل نظر انداز کرتے ہیں۔ وہ تصویر کو پکسل بہ پکسل دکھاتے ہیں، اس لیے 1000 پکسل تصویر 1000 اسکرین پکسل گھیرتی ہے چاہے اس کا ٹیگ کچھ بھی کہے۔</p>\n<p>ویب پر اہمیت ڈسپلے سائز کے مقابلے میں پکسل ابعاد کی ہوتی ہے۔ 800 پکسل چوڑی دکھائی گئی تصویر فائل میں تقریباً 800 سے 1600 پکسل ہونی چاہیے۔</p>\n<p>ویب تصویر پر 300 DPI سیٹ کرنا اس کے دیکھنے یا لوڈ ہونے کے بارے میں کچھ نہیں بدلتا۔ فائل سائز وہی رہتا ہے، ڈسپلے وہی رہتا ہے، اور واحد فرق ہیڈر میں نمبر ہے۔</p>\n<p>ویب اصول اس لیے آسان ہے: ابعاد کو ڈسپلے سے ملائیں، رفتار کے لیے فائل کمپریس کریں، اور DPI کو مکمل بھول جائیں جب تک تصویر پرنٹ پر نہ جائے۔</p>\n<h2 id=\"the-72-dpi-myth\">72 DPI کا افسانہ</h2>\n<p>تصویر سازی میں سب سے مستقل افسانہ یہ ہے کہ ویب تصاویر 72 DPI ہونی چاہیے۔ یہ ابتدائی Macintosh سے آتا ہے، جس کی اسکرین فی انچ 72 پکسل دکھاتی تھی، اور یہ تب سے چپکا ہوا ہے۔</p>\n<p>جدید اسکرین 100 سے 400 PPI سے زیادہ تک ہوتی ہیں، اس لیے کوئی واحد DPI قدر ان سب کو بیان نہیں کرتی۔ ویب تصویر پر 72 DPI ٹیگ تاریخی حادثہ ہے، ضرورت نہیں۔</p>\n<p>افسانہ اس لیے بچتا ہے کہ سافٹ ویئر ڈیفالٹ سے فائلوں میں 72 لکھتا رہتا ہے۔ کیمرے، اسکرین شاٹس، اور ایکسپورٹ سب 72 DPI مہر لگاتے ہیں جب ان کے پاس بہتر قدر نہ ہو۔</p>\n<p>ویب پر نمبر کو نظر انداز کریں۔ ویب تصویر کو اس کے پکسل ابعاد اور فائل سائز سے پرکھیں، اور DPI ٹیگ کو اکیلا چھوڑ دیں جب تک تصویر پرنٹ پر نہ جائے۔</p>\n<h2 id=\"the-300-dpi-standard\">پرنٹ کے لیے 300 DPI معیار</h2>\n<p>300 DPI معیار انسانی آنکھ کی حدوں کی وجہ سے موجود ہے۔ عام پڑھنے کے فاصلے پر آنکھ فی انچ تقریباً 300 نقطے سے باریک تفصیل حل نہیں کر سکتی۔</p>\n<p>اسی لیے کتاب پرنٹر، جریدے، اور پیکجنگ فرمیں سب 300 مانگتی ہیں۔ یہ وہ نقطہ ہے جہاں ہاتھ میں رکھے پرنٹ کے لیے کوالٹی بہتر ہونا بند کرتی ہے، اور اس سے زیادہ مانگنا ضیاع ہے۔</p>\n<p>فائن آرٹ اور آرکائیو کام 600 DPI پر جاتا ہے کیونکہ ان پرنٹ کو قریب سے جانچا جاتا ہے، کبھی میگنفکیشن کے تحت۔ اضافی کثافت باریک تفصیل محفوظ رکھتی ہے۔</p>\n<p>600 DPI سے آگے جانا پرنٹ کے لیے تقریباً کبھی مفید نہیں ہوتا۔ پرنٹر نقطوں کو کافی درستگی سے نہیں رکھ سکتا، اور فائل بغیر نظر آنے والے فائدے کے بہت بڑی ہو جاتی ہے۔</p>\n<h2 id=\"screens-and-retina\">اسکرین، ریٹینا، اور PPI</h2>\n<p>ریٹینا اور ہائی ڈینسٹی اسکرین نے ویب حساب بدل دیا۔ 2x ڈسپلے والا فون ہر CSS پکسل کے لیے دو جسمانی پکسل استعمال کرتا ہے، اس لیے تصویر کو دوگنا پکسل چاہیے ہوتے ہیں۔</p>\n<p>یہ PPI اثر ہے، DPI اثر نہیں۔ اسکرین فی انچ زیادہ پکسل پیک کرتی ہے، اس لیے تصویر فائل میں ڈسپلے کے فی انچ زیادہ پکسل ہونے چاہیے تاکہ ساتھ رہے۔</p>\n<p>عملی جواب تصاویر کو ڈسپلے سائز سے دوگنا پیش کرنا ہے۔ 400 CSS پکسل چوڑی دکھائی گئی تصویر فائل میں تقریباً 800 پکسل ہونی چاہیے، جو تیز لگتی ہے۔</p>\n<p>اس میں سے کوئی بھی DPI ٹیگ شامل نہیں کرتا۔ فائل ابعاد کام کرتے ہیں، اور ٹیگ ہیڈر میں بغیر پڑھے بیٹھا رہتا ہے جبکہ براؤزر پکسل رینڈر کرتا ہے۔</p>\n<h2 id=\"print-size-math\">پرنٹ سائز ریاضی: پکسل تقسیم DPI</h2>\n<p>پرنٹ سائز کا فارمولا ایک تقسیم ہے: پکسل چوڑائی تقسیم DPI برابر پرنٹ شدہ چوڑائی انچ میں۔ 300 DPI پر 3000 پکسل تصویر 10 انچ چوڑی پرنٹ ہوتی ہے۔</p>\n<p>اپنی ضرورت کے سائز سے پیچھے کام کریں۔ 300 DPI پر 8 بائی 10 انچ پرنٹ کو 2400 بائی 3000 پکسل چاہیے ہوتے ہیں، اس لیے اس سے چھوٹی کوئی فائل اس سائز پر نرم پرنٹ ہو گی۔</p>\n<p>PPI کبھی اس فارمولے میں داخل نہیں ہوتا۔ تصویر پکڑنے والے آلے کی اسکرین کثافت پرنٹ شدہ نتیجے سے غیر متعلق ہے؛ صرف پکسل تعداد اور DPI ٹیگ اہمیت رکھتے ہیں۔</p>\n<p>پکسل تعداد کی تصدیق کے لیے <a href=\"/ur/tasveer-ka-size-dekhein/\">image dimensions checker</a> استعمال کریں، پھر ٹیگ سیٹ کرنے کے لیے <a href=\"/ur/tasveer-ka-dpi-badlein/\">image DPI changer</a> استعمال کریں۔ دونوں ٹول مل کر پرنٹ سوال کا مکمل جواب دیتے ہیں۔</p>\n<h2 id=\"metadata-vs-pixels\">میٹا ڈیٹا بمقابلہ پکسل: بنیادی فرق</h2>\n<p>DPI ٹیگ میٹا ڈیٹا ہے: فائل ہیڈر میں چند بائٹ جو مطلوبہ پرنٹ کثافت بیان کرتے ہیں۔ اسے بدلنا ان بائٹ کو دوبارہ لکھتا ہے اور ہر پکسل کو اچھوتا چھوڑتا ہے۔</p>\n<p>PPI ہارڈ ویئر ہے: اسکرین کی جسمانی کثافت۔ اسے فائل ایڈٹ کر کے نہیں بدلا جا سکتا، کیونکہ یہ تصویر کے بجائے ڈسپلے آلے کو بیان کرتا ہے۔</p>\n<p>یہ فرق بتاتا ہے کہ DPI تبدیلیاں نقصان سے پاک اور فوری کیوں ہوتی ہیں، جبکہ PPI تبدیلیاں ناممکن ہوتی ہیں۔ ایک فائل پر لیبل ہے، اور دوسرا آلے کے بارے میں حقیقت ہے۔</p>\n<p>جب کوئی کہے کہ تصویر کی ریزولوشن کم ہے تو پوچھیں کہ اس کا مطلب کون سا ہے۔ اگر اس کا مطلب کم پکسل ہیں تو حل بڑی فائل ہے۔ اگر اس کا مطلب کم DPI ٹیگ ہے تو حل تیز مہر ہے۔</p>\n<h2 id=\"when-to-change-dpi\">DPI کب بدلیں</h2>\n<p>DPI تب بدلیں جب پرنٹ ورک فلو اس کا مطالبہ کرے۔ کتاب پلیٹفارم، جریدے، اور پرنٹ شاپ ٹیگ چیک کرتے ہیں، اور غلط قدر والی فائل کسی کے دیکھنے سے پہلے مسترد ہو جاتی ہے۔</p>\n<p>DPI تب بدلیں جب ٹیگ غائب ہو۔ بغیر DPI قدر والی تصویر پرنٹ سائز کو غیر متعین چھوڑتی ہے، اور اسے کھولنے والا سافٹ ویئر اندازہ لگائے گا، اکثر برا۔</p>\n<p>DPI تب بدلیں جب اسکرین تصویر کو پرنٹ کے لیے دوبارہ استعمال کریں۔ 300 DPI پر مہر شدہ اسکرین شاٹ پرنٹ ورک فلو کو مطمئن کرتا ہے، بشرطیکہ اس کے پکسل سائز کے لیے کافی ہوں۔</p>\n<p>ویب کے لیے DPI نہ بدلیں۔ اس کا ڈسپلے یا لوڈنگ پر کوئی اثر نہیں، اور وقت ابعاد ملانے اور فائل کمپریس کرنے میں بہتر خرچ ہوتا ہے۔</p>\n<h2 id=\"when-dpi-does-not-help\">DPI کب مدد نہیں کرتا</h2>\n<p>DPI مدد نہیں کرتا جب پکسل بہت کم ہوں۔ 300 DPI پر مہر شدہ 400 بائی 400 تھمب نیل پھر بھی 400 بائی 400 تھمب نیل ہے، اور یہ صرف ایک انچ سے زیادہ چوڑا پرنٹ ہوتا ہے۔</p>\n<p>DPI دھندلی تصویر کی مدد نہیں کرتا۔ دھندلا پن پکسل میں رہتا ہے، اور کوئی میٹا ڈیٹا ایڈٹ فوکس سے باہر تصویر یا ہلتے اسکرین شاٹ کو تیز نہیں کر سکتا۔</p>\n<p>DPI اسکرین پر مدد نہیں کرتا۔ براؤزر ٹیگ کو نظر انداز کرتا ہے، اس لیے 300 DPI پر سیٹ شدہ ویب تصویر 72 DPI پر سیٹ شدہ اسی تصویر جیسی لگتی ہے۔</p>\n<p>DPI فائل سائز کی بھی مدد نہیں کرتا۔ ٹیگ چند بائٹ ہے، اس لیے اسے بدلنا ایسی فائل کو نہیں سکڑتا جسے پورٹل بھاری ہونے پر مسترد کرے۔</p>\n<h2 id=\"workflow-for-print\">پرنٹ ورک فلو جو درست کرتا ہے</h2>\n<p>اپنی ضرورت کے جسمانی سائز سے شروع کریں، انچ میں۔ پکسل حاصل کرنے کے لیے 300 سے ضرب دیں، اور ابعاد چیکر سے تصدیق کریں کہ آپ کی فائل اس نمبر پر پورا اترتی ہے۔</p>\n<p>DPI ٹیگ کو DPI چینجر سے 300 پر سیٹ کریں، اور Verified DPI بیج تلاش کریں۔ بیج تصدیق کرتا ہے کہ ٹیگ درست محفوظ ہے اور دوسرے سافٹ ویئر میں ویسے ہی پڑھا جائے گا۔</p>\n<p>مکمل رن سے پہلے ٹیسٹ پرنٹ یا پروف بھیجیں۔ پروف ان مسائل کو پکڑتا ہے جو نمبر نہیں کر سکتے، جیسے کاغذ پر بدلنے والے رنگ یا پرنٹ پر غائب ہونے والی تفصیل۔</p>\n<p>مہر شدہ فائل اور اصل کو ساتھ رکھیں۔ اگر پرنٹر بعد میں مختلف DPI مانگے تو پہلے سے مہر شدہ کاپی کے بجائے اصل کو دوبارہ مہر لگائیں۔</p>\n<h2 id=\"workflow-for-web\">ویب ورک فلو جو DPI کو نظر انداز کرتا ہے</h2>\n<p>CSS پکسل میں ڈسپلے سائز سے شروع کریں۔ ریٹینا اسکرین کے لیے اسے دوگنا کریں، اور وہ دوگنا نمبر پکسل چوڑائی ہے جو آپ کی فائل کو چاہیے۔</p>\n<p>فائل کو اس وقت تک کمپریس کریں جب تک کوالٹی نقصان بمشکل نظر آئے، پھر ایک قدم پیچھے جائیں۔ یہ سب سے چھوٹی فائل ہے جو پھر بھی اچھی لگتی ہے، اور یہی وہ ہے جو آپ کے زائرین دیکھیں گے۔</p>\n<p>ابعاد کو ابعاد چیکر اور وزن کو کمپریسر سے چیک کریں۔ وہ دو نمبر، DPI نہیں، طے کرتے ہیں کہ تصویر ویب کے لیے درست ہے یا نہیں۔</p>\n<p>DPI ٹیگ کو بالکل ویسے چھوڑ دیں جیسے یہ کیمرے یا ایکسپورٹ سے آیا تھا۔ اسے بدلنا قدم ضائع کرتا ہے، اور کوئی براؤزر اسے کبھی نہیں پڑھے گا۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: DPI بمقابلہ PPI</h2>\n<p>DPI کا مطلب dots per inch ہے، پرنٹ تصور۔ یہ فائل میں میٹا ڈیٹا ٹیگ کے طور پر رہتا ہے، یہ پرنٹ شدہ سائز طے کرتا ہے، اور آپ اسے پرنٹ ورک فلو کے لیے DPI چینجر سے بدلتے ہیں۔</p>\n<p>PPI کا مطلب pixels per inch ہے، اسکرین تصور۔ یہ ڈسپلے ہارڈ ویئر کو بیان کرتا ہے، یہ طے کرتا ہے کہ اسکرین کتنی تیز لگتی ہے، اور آپ اسے فائل ایڈٹ کر کے نہیں بدل سکتے۔</p>\n<p>ویب پر پکسل ابعاد اور فائل سائز کی پرواہ کریں۔ پرنٹ میں پکسل ابعاد اور DPI ٹیگ کی پرواہ کریں۔ دونوں دنیا مختلف نمبر استعمال کرتی ہیں، اور انہیں ملانا غلطیاں پیدا کرتا ہے۔</p>\n<p>عملی ٹولز کے لیے <a href=\"/ur/blog/tasveer-dpi-changer-rehnumai/\">Image DPI Changer: Complete Guide</a> اور <a href=\"/ur/blog/tasveer-ka-dpi-kaise-badlein/\">How to Change Image DPI</a> میں مراحل دیکھیں۔ متعلقہ نمبروں کے لیے <a href=\"/ur/blog/tasveer-dimensions-vs-resolution-vs-file-size/\">Dimensions vs Resolution vs File Size Explained</a> پڑھیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"کیا DPI اور PPI ایک ہی چیز ہیں؟","answer":"نہیں، اگرچہ کچھ سافٹ ویئر اسی فائل ٹیگ کے لیے لیبل ایک دوسرے کی جگہ استعمال کرتے ہیں۔ DPI کاغذ پر فی انچ سیاہی نقطے گنتا ہے، جبکہ PPI اسکرین پر فی انچ جسمانی پکسل گنتا ہے۔ فائل ٹیگ پرنٹ تصور ہے، اسکرین تصور نہیں۔"},{"question":"کیا 300 DPI تصویر ویب سائٹ پر 72 DPI تصویر سے بہتر لگتی ہے؟","answer":"نہیں۔ براؤزر DPI ٹیگ کو نظر انداز کرتے ہیں اور تصویر کو پکسل بہ پکسل دکھاتے ہیں، اس لیے دونوں فائلیں اسکرین پر ایک جیسی لگتی ہیں۔ ویب تیزی پکسل ابعاد سے آتی ہے، DPI قدر سے نہیں۔"},{"question":"پرنٹ شاپ 300 DPI کیوں مانگتی ہیں جبکہ اسکرین 72 DPI استعمال کرتی ہیں؟","answer":"پرنٹ اور اسکرین مختلف میڈیا ہیں جن کی کثافت ضرورتیں مختلف ہیں۔ پڑھنے کے فاصلے پر آنکھ کاغذ پر فی انچ تقریباً 300 نقطے حل کرتی ہے، اس لیے پرنٹ کو ہموار لگنے کے لیے وہ کثافت چاہیے ہوتی ہے۔ اسکرین پکسل دکھاتی ہیں، سیاہی نہیں۔"},{"question":"کیا میں کم PPI اسکرین تصویر کو زیادہ DPI پرنٹ تصویر میں بدل سکتا ہوں؟","answer":"صرف میٹا ڈیٹا معنوں میں۔ آپ کسی بھی تصویر پر 300 DPI ٹیگ مہر لگا سکتے ہیں، مگر ٹیگ پکسل نہیں بڑھاتا۔ کم پکسل والا اسکرین شاٹ 300 DPI پر پھر بھی چھوٹا پرنٹ ہو گا۔ اصل پرنٹ کوالٹی کو کافی پکسل چاہیے ہوتے ہیں۔"},{"question":"پرنٹنگ کے لیے میری فون تصاویر کا PPI کیا ہونا چاہیے؟","answer":"فون تصاویر کا پرنٹ معنوں میں PPI نہیں ہوتا؛ ان کے پکسل ابعاد ہوتے ہیں اور عام طور پر کوئی DPI ٹیگ نہیں ہوتا۔ پرنٹ چوڑائی انچ میں تلاش کرنے کے لیے پکسل چوڑائی کو 300 سے تقسیم کریں۔ 4000 پکسل چوڑی فون تصویر 300 DPI پر 13 انچ سے زیادہ چوڑی پرنٹ ہوتی ہے۔"},{"question":"کیا مجھے سوشل میڈیا اپ لوڈ کے لیے DPI کی فکر کرنی چاہیے؟","answer":"نہیں۔ سوشل پلیٹفارم تصاویر کو اسکرین پر دکھاتے ہیں، جہاں صرف پکسل ابعاد اور فائل سائز اہمیت رکھتے ہیں۔ درست ابعاد اور معقول کمپریس شدہ فائل اپ لوڈ کریں، اور سوشل کے لیے DPI ٹیگ کو مکمل نظر انداز کریں۔"}];
